#include <iostream>
#include <fstream>
#include <vector>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int k = 3;
    double prog = 7.0;
    int suma = 0;
    for (int i = 0; i < k; i++) suma += dane[i];
    cout << fixed << setprecision(2);
    cout << "Srednie ruchome (K=" << k << "):" << endl;
    int powyzej = 0;
    double maxAvg = 0;
    int maxOkno = 0;
    for (int i = 0; i <= (int)dane.size() - k; i++) {
        if (i > 0) suma += dane[i + k - 1] - dane[i - 1];
        double avg = (double)suma / k;
        cout << "   Okno " << i + 1 << ": " << avg << endl;
        if (avg > prog) powyzej++;
        if (avg > maxAvg) { maxAvg = avg; maxOkno = i + 1; }
    }
    cout << "Okna powyzej " << prog << ": " << powyzej << endl;
    cout << "Najwyzsza srednia: " << maxAvg << " (okno " << maxOkno << ")" << endl;
    return 0;
}
